  // ── cookies ─────────────────────────────────────────────────────
  "cookies.title": "Preferencias de cookies",
  "cookies.body": "<strong class=\"font-semibold text-surface-900 dark:text-white\">Usamos cookies</strong> para mejorar tu navegación y analizar nuestro tráfico. Al pulsar «Aceptar», consientes",
